import{describe,it,expect}from"vitest";import Engine from"../../frontend/js-modules/travel/seasonal-recommend-engine.js";const GOA={id:"rec-goa",name:"Goa",region:"west",tags:["beaches","food"],budget:"mid",seasons:["winter"],image:"goa.png",description:"Beaches"},MANALI={id:"rec-manali",name:"Manali",region:"north",tags:["mountains","adventure"],budget:"mid",seasons:["summer","winter"],image:"manali.png",description:"Mountains"},RISHIKESH={id:"rec-rishikesh",name:"Rishikesh",region:"north",tags:["adventure","spiritual"],budget:"budget",seasons:["year-round"],image:"rishikesh.png",description:"Yoga"},RANTHAMBORE={id:"rec-ranthambore",name:"Ranthambore",region:"west",tags:["wildlife"],budget:"mid",seasons:["winter"],image:"rb.png",description:"Tigers"},DESTINATIONS=[GOA,MANALI,RISHIKESH,RANTHAMBORE],EVENTS=[{id:"goa-carnival",name:"Goa Carnival",category:"Culture",tags:["music"],state:"Goa",startMonth:2,endMonth:2,popularity:8},{id:"pushkar-fair",name:"Pushkar Camel Fair",category:"Culture",tags:["fair"],state:"Rajasthan",startMonth:10,endMonth:11,popularity:8}];describe("monthSeason",()=>{it("maps December to winter",()=>{expect(Engine.monthSeason(12)).toBe("winter")}),it("maps May to summer",()=>{expect(Engine.monthSeason(5)).toBe("summer")}),it("maps August to monsoon",()=>{expect(Engine.monthSeason(8)).toBe("monsoon")})}),describe("monthInRange",()=>{it("handles a normal (non-wrapping) range",()=>{expect(Engine.monthInRange(10,10,11)).toBe(!0),expect(Engine.monthInRange(9,10,11)).toBe(!1)}),it("handles a year-wrapping range",()=>{expect(Engine.monthInRange(12,11,2)).toBe(!0),expect(Engine.monthInRange(1,11,2)).toBe(!0),expect(Engine.monthInRange(6,11,2)).toBe(!1)})}),describe("computeMonthScore",()=>{it("gives a beach destination a peak score in its tagged winter season",()=>{const e=Engine.computeMonthScore(GOA,12);expect(e.score).toBe(3),expect(e.label).toBe("Peak season")}),it('downgrades a beach destination to "avoid" during the monsoon',()=>{const e=Engine.computeMonthScore(GOA,8);expect(e.score).toBe(0),expect(e.label).toMatch(/Avoid/)}),it("downgrades a wildlife destination during the monsoon (park closures)",()=>{const e=Engine.computeMonthScore(RANTHAMBORE,7);expect(e.score).toBe(0)}),it("scores a year-round destination reasonably in any month",()=>{expect(Engine.computeMonthScore(RISHIKESH,8).score).toBeGreaterThanOrEqual(2),expect(Engine.computeMonthScore(RISHIKESH,1).score).toBeGreaterThanOrEqual(2)}),it("gives a mountain destination its peak score in a tagged month",()=>{expect(Engine.computeMonthScore(MANALI,6).score).toBe(3),expect(Engine.computeMonthScore(MANALI,12).score).toBe(3)})}),describe("getFestivalsForDestination",()=>{it("finds a festival in the matching state and month window",()=>{const e=Engine.getFestivalsForDestination(GOA,2,EVENTS);expect(e.map(e=>e.id)).toContain("goa-carnival")}),it("returns nothing outside the festival month window",()=>{const e=Engine.getFestivalsForDestination(GOA,6,EVENTS);expect(e).toHaveLength(0)}),it('matches region-mapped states, e.g. Rajasthan under the "west" region',()=>{const e=Engine.getFestivalsForDestination(RANTHAMBORE,10,EVENTS);expect(e.map(e=>e.id)).toContain("pushkar-fair")})}),describe("rankDestinationsForMonth",()=>{it('excludes destinations scored "avoid" for the month',()=>{const e=Engine.rankDestinationsForMonth(DESTINATIONS,8,{},EVENTS).map(e=>e.dest.id);expect(e).not.toContain("rec-goa"),expect(e).not.toContain("rec-ranthambore")}),it("ranks a festival-boosted destination above one without a festival, all else equal",()=>{const e=Engine.rankDestinationsForMonth([GOA],12,{},EVENTS);expect(e[0].dest.id).toBe("rec-goa"),expect(e[0]).toHaveProperty("climate"),expect(e[0]).toHaveProperty("total")}),it("boosts destinations matching requested interests",()=>{const e=Engine.rankDestinationsForMonth(DESTINATIONS,12,{interests:["wildlife"]},EVENTS),t=Engine.rankDestinationsForMonth(DESTINATIONS,12,{},EVENTS),n=e.find(e=>"rec-ranthambore"===e.dest.id).total,o=t.find(e=>"rec-ranthambore"===e.dest.id).total;expect(n).toBeGreaterThan(o)}),it("respects the limit option",()=>{const e=Engine.rankDestinationsForMonth(DESTINATIONS,12,{},EVENTS,{limit:1});expect(e).toHaveLength(1)})}),describe("getAlternatives",()=>{it("suggests a tag-overlapping, well-timed alternative for an avoided destination",()=>{const e=Engine.getAlternatives(RANTHAMBORE,DESTINATIONS,7,3);expect(e.every(e=>"rec-ranthambore"!==e.id)).toBe(!0)}),it("never suggests the destination itself",()=>{const e=Engine.getAlternatives(GOA,DESTINATIONS,8,3);expect(e.map(e=>e.id)).not.toContain("rec-goa")})}),describe("getSeasonalInsights",()=>{it("tallies destinations into peak/good/off/avoid buckets that sum to the total",()=>{const e=Engine.getSeasonalInsights(DESTINATIONS,8,EVENTS),t=e.peakCount+e.goodCount+e.offSeasonCount+e.avoidCount;expect(t).toBe(DESTINATIONS.length),expect(e.monthName).toBe("August")}),it("surfaces festivals happening in the requested month",()=>{const e=Engine.getSeasonalInsights(DESTINATIONS,2,EVENTS);expect(e.festivals.map(e=>e.id)).toContain("goa-carnival")})}),describe("buildSeasonalReason",()=>{it("includes climate note, festival mention, and matched interests",()=>{const e=Engine.buildSeasonalReason({climate:{note:"Great weather.",score:3,label:"Peak season"},festivals:[{name:"Test Fest"}],matchedInterests:["beaches"]});expect(e).toContain("Great weather."),expect(e).toContain("Test Fest"),expect(e).toContain("beaches")})});